pgroup_id = #{productGroupPrice.pgroupId}, price_type_id = #{productGroupPrice.priceTypeId}, `set_type` = #{productGroupPrice.setType}, cost_method = #{productGroupPrice.costMethod}, cond_update_pro = #{productGroupPrice.ApplyToAllProduct}, modified = NOW(), modified_by = #{productGroupPrice.modifiedBy}
