mapper.select:
SELECT COUNT(*) FROM products WHERE is_active = 1 AND code!='' AND barcode!=''
AND unit_cost >= #{filter.fromCost}
AND unit_cost <= #{filter.toCost}
AND (products.code LIKE CONCAT("%", #{filter.searchText}, "%") OR products.name LIKE CONCAT("%", #{filter.searchText}, "%") OR uoms.name LIKE CONCAT("%", #{filter.searchText}, "%"))
AND id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.groupId})

SELECT products.id AS id, products.code AS code, products.name AS name, uoms.name AS uom, products.unit_cost AS unitCost,
(products.unit_cost * #{filter.value} / 100) + products.unit_cost AS price
products.unit_cost + #{filter.value} AS price
FROM products LEFT JOIN uoms ON uoms.id = products.price_uom_id WHERE products.is_active = 1 AND products.code!='' AND products.barcode!=''
AND unit_cost >= #{filter.fromCost}
AND unit_cost <= #{filter.toCost}
AND (products.code LIKE CONCAT("%", #{filter.searchText}, "%") OR products.name LIKE CONCAT("%", #{filter.searchText}, "%") OR uoms.name LIKE CONCAT("%", #{filter.searchText}, "%"))
AND products.id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.groupId})
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(products.id) FROM products LEFT JOIN uoms ON uoms.id = products.price_uom_id WHERE products.is_active = 1 AND products.code!='' AND products.barcode!=''
AND unit_cost >= #{filter.fromCost}
AND unit_cost <= #{filter.toCost}
AND products.id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.groupId})

